const tabId = 2017691829;

async function searchAmazonProducts(query) {
  await tool.navigate({ tabId, url: `https://www.amazon.com/s?k=${encodeURIComponent(query)}` });
  await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 10000 });
  return await browserjs(tabId, () => {
    const cards = Array.from(document.querySelectorAll("div[data-asin]")).filter(c => c.getAttribute("data-asin")?.trim().length > 3);
    const seen = new Set();
    const results = [];

    for (const card of cards) {
      const asin = card.getAttribute("data-asin");
      if (seen.has(asin)) continue;
      seen.add(asin);

      const titleEl = card.querySelector("h2") || card.querySelector("a.a-text-normal");
      const linkEl = card.querySelector("h2 a") || card.querySelector("a[href*='/dp/']");
      const priceEl = card.querySelector(".a-price .a-offscreen") || card.querySelector(".a-price");
      const ratingEl = card.querySelector(".a-icon-alt");

      const title = titleEl ? titleEl.innerText.trim() : null;
      let url = linkEl ? linkEl.href.split("?")[0] : null;
      const price = priceEl ? priceEl.innerText.trim() : null;
      const rating = ratingEl ? ratingEl.innerText.trim() : null;

      if (title && url && url.includes("/dp/") && !url.includes("sponsored") && title.length > 15) {
        results.push({ asin, title, url, price, rating });
      }
    }
    return results;
  });
}

