// Let's write a helper that navigates to a URL on Amazon or directly inspects a product page
async function getAmazonProductDetails(asinOrUrl) {
  const url = asinOrUrl.startsWith("http") ? asinOrUrl : `https://www.amazon.com/dp/${asinOrUrl}`;
  await tool.navigate({ tabId, url });
  await tool.wait_for({ tabId, condition: "load_state", value: "domcontentloaded", timeout_ms: 10000 });

  return await browserjs(tabId, () => {
    const title = document.querySelector("#productTitle")?.innerText.trim();
    const priceWhole = document.querySelector(".a-price .a-price-whole")?.innerText.replace(/\n/g, '').trim();
    const priceFraction = document.querySelector(".a-price .a-price-fraction")?.innerText.replace(/\n/g, '').trim();
    const price = priceWhole ? `$${priceWhole}${priceFraction ? '.' + priceFraction : ''}` : document.querySelector(".a-price .a-offscreen")?.innerText.trim() || "not shown";

    // Overview / feature bullets
    const bullets = Array.from(document.querySelectorAll("#feature-bullets li, #productFactsDesktopExpander li"))
      .map(li => li.innerText.trim())
      .filter(t => t.length > 5);

    // Product details table
    const details = {};
    const rows = document.querySelectorAll("#productDetails_techSpec_section_1 tr, #detailBullets_feature_div li, #productOverview_feature_div tr");
    rows.forEach(r => {
      const th = r.querySelector("th, span.a-text-bold")?.innerText.replace(/[\n:]+/g, ' ').trim();
      const td = r.querySelector("td, span:not(.a-text-bold)")?.innerText.replace(/\n+/g, ' ').trim();
      if (th && td) details[th] = td;
    });

    // Rating and review count
    const rating = document.querySelector("#acrPopover")?.title || document.querySelector(".a-icon-alt")?.innerText;
    const reviewCount = document.querySelector("#acrCustomerReviewText")?.innerText;

    // Delivery info
    const delivery = document.querySelector("#mir-layout-DELIVERY_BLOCK, #deliveryBlockMessage")?.innerText.replace(/\n+/g, ' ').trim() || "not shown";

    return {
      title,
      price,
      rating,
      reviewCount,
      bullets: bullets.slice(0, 8),
      details,
      delivery,
      url: window.location.href
    };
  });
}

