async function searchGoogle(query) {
  await tool.navigate({ tabId, url: `https://www.google.com/search?q=${encodeURIComponent(query)}` });
  await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 10000 });
  return await browserjs(tabId, () => {
    const links = Array.from(document.querySelectorAll("a[href^='http']"));
    const seen = new Set();
    const res = [];
    for (const a of links) {
      const url = a.href;
      const text = a.innerText.trim();
      if (!url.includes("google.com") && !seen.has(url) && text.length > 5) {
        seen.add(url);
        res.push({ text: text.replace(/\n+/g, ' ').slice(0, 80), url });
      }
    }
    return res;
  });
}

